import{_ as e,o as a,c as t,a3 as _}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/104-解决冲突的安全型法则.md","filePath":"books/attached/104-解决冲突的安全型法则.md","lastUpdated":1794316978000}'),o={name:"books/attached/104-解决冲突的安全型法则.md"};function r(s,p,n,c,d,l){return a(),t("div",null,[...p[0]||(p[0]=[_('<h3 id="解决冲突的安全型法则" tabindex="-1">解决冲突的安全型法则 <a class="header-anchor" href="#解决冲突的安全型法则" aria-label="Permalink to &quot;解决冲突的安全型法则&quot;">​</a></h3><p>接下来，我们就来更加细致地了解安全型人群在与伴侣产生分歧的时候，所用的五条法则。</p><p>化解冲突的五条法则</p><p>1.基于对方的幸福着想。</p><p>2.坚持关注问题本身，就事论事。</p><p>3.避免扩大冲突。</p><p>4.愿意包容对方。</p><p>5.有效地沟通双方的感受与需要。</p><p>1.基于对方的幸福着想：</p><p>弗兰克（Frank）非常喜欢户外旅行，夏天喜欢到伯克郡去，在从父母那里继承下来的小屋里避暑。但珊迪（Sandy）却不以为然。她觉得不停地打包行李非常麻烦，也很讨厌无休止地长途驾驶。对她来说，这整个过程是痛苦大于开心的。在他们意识到两个人一味坚持自己的意愿，而忽视对方的感受，最终是会弄得两边都不开心之前，还会时不时有些争吵。他们后来发现了一种有效的机制，即使两人的喜好天生不同，依然可以用于制定二人原本争执不下的闲暇时间计划。现在，当珊迪感觉到城市生化对于弗兰克来说压力太大，她就会稍微委屈自己，与弗兰克同去森林探险。而同样地，当弗兰克发现珊迪对旅途有些不胜其烦时，他们就会在城市里呆比较长的时间。而在这段时间，弗兰克为了保持自己的愉悦心情，就只能计划一些户外活动以弥补。这并不是个完美无缺的机制，有时候他们也会陷入沮丧和抱怨，但他们有能力化解这些问题，会尽自己的最大努力去包容对方。</p><p>弗兰克和珊迪都了解良好关系的基本前提——对方的幸福对自己来说也十分重要。忽视对方的意愿，将会直接影响到自己的情绪、满意度甚至是生理健康。我们总是认为冲突是场零和游戏：不是你死就是我亡。然而依恋理论告诉我们，我们的幸福其实是与伴侣互相依存的，两者是没法独立存在的。即使是爱好相去甚远，珊迪和弗兰克依然让双方处于一种礼尚往来之中，两人都能感受到对方照顾着自己的感受，从而获得满足感。从依恋关系的角度看，这的确是一段报酬丰厚的经历。</p><p>2.坚持关注问题本身，就事论事</p><p>“在我们刚开始约会的时候，”凯莉（Kelly）回忆道，“乔治（George）跟我都走到了他公寓门口，但是没有请我进去。他说房子在翻新，让我看到里头的杂乱会让他不太自在。”我是个多疑的人，他的解释在我这里不太适用。我武断地得到另一番结论，脑海中浮现出这样的图景：他浴室里还有另一把牙刷，床上还有另外女人的内衣。他察觉到我心情的变化，问我怎么了。我说他肯定有什么事情瞒着我，那次约会不欢而散。</p><p>然而，他第二天晚上还是约我了。他开了公寓楼下的门，我还在上楼梯，他就开着房门，手里还拿着扫帚招手要我进去，连说三声‘欢迎！’房间真的乱七八糟，但我们相视一笑，不快都烟消云散。”</p><p>乔治之所以能够扭转局势，是因为他属于安全型依恋风格。虽然他的回应方式看上去十分自然，但仔细一想就会发现，并不是每个人都本能做出这样的回应。乔治始终能够做到关注问题的本身。当属于焦虑型依恋风格的凯莉偏题主题，使用主观臆断的时候，乔治看穿了她的防御行为，准确抓住了困扰她的关键点。他的行为与相关研究的结果完美契合。伊利诺斯州立大学的依恋关系实验室负责人加里·格里西（Garry Greasey）对依恋理论视角下的冲突管理研究有着特别的兴趣。他与同样来自伊利诺伊州立大学心理学院的马修·赫松·麦金尼斯（Matthew Hesson McInnis）一同研究发现，安全型依恋风格的人，在理解伴侣的希求以及将关注点焦距于事情本身上面，有着更强的能力。通过快速回应凯莉的担忧，并且有效快速地将之解决，乔治避免了更大的冲突。他的这种能力，建立起了一种裨益于双方的安全型关系：凯莉深知自己有一个以她的幸福为己任的伴侣，而乔治发现自己可以被对方全权接受，不管是凌乱还是整洁的自己都无所谓。只要两人都抱着积极的意愿解决问题，他们就会发现自己得到了聆听和尊重，两人的关系也会更进一步。</p><p>当然，即使是安全型的人，也并不一定能如此体面地解决所有的问题。他们也有情绪失控，或者忽视伴侣需求的情形。</p><p>3.避免扩大冲突</p><p>虽然五十几岁的泰瑞（Terry）和艾利克斯（Alex）都属于安全型依恋风格，他们还是争争吵吵、针锋相对地过了三十多年了。泰瑞在购物之前，会给艾利克斯列一份非常详细的购物清单——番茄碎、全麦面包还有一袋巴里拉意大利面。几小时后艾利克斯带着东西回来，跟清单上差不多但又不太一样。他买了另一个牌子的意大利面，还买了番茄意面而不是清单上写的番茄碎。泰瑞非常不开心，说艾利克斯太没用，还情绪激动地宣称自己以后要独自去商场。而艾利克斯也同样怒火中烧，一把抓起货品就冲出家门。他最终还是买回了正确的东西，但那一整天都因为两人的对峙而毁掉了。</p><p>虽然泰瑞和艾利克斯都很在意对方，但并没有真正正确地看待两人的冲突。如果他们好好审视，就会发现换种方式解决问题会更好些。艾利克斯是个马大哈，他只是不怎么在意细节，这也就是为什么两人生活中有些事对他来说很难。而泰瑞又恰恰很重视细节，她即使逼着自己忽视它们，也无济于事。当然，这也并不意味着泰瑞就要把所有责任都归咎于自己。另一种建设性的解决方式就是按顺序购买。泰瑞可以在艾利克斯采购的时候打电话给他，确保他篮子里的商品核对正确，按照顺序让艾利克斯拿取商品，拿到后就在商品下面做记号，也可以由艾利克斯帮忙操持家务，而泰瑞自己去采购。总之他们可以找一些更加合拍、更少对峙的方式，并且运用到生活中。</p><p>不过，还有一件值得注意的事。虽然他们常为一点小事争吵，但他们其实尽可能避开了那些摧毁他们关系的雷区。最重要的是，他们不会让冲突蔓延到其他的领域，或者变得不可控制。他们会避免对伴侣做出诋毁性的评价，也不会通过一些以偏概全的结论来伤害对方。他们总会将争吵的范围限制在事件本身，不会将怒火转移到其他的地方去。虽然泰瑞会很生气地威胁艾利克斯，说自己要一个人去购物——当然她有时候的确会付诸行动，但是她绝不会将怒火扩散到“我真是受够你了！”或者“你还能做什么？自己弄晚饭吧，我不管了！”之类的话。</p><p>4.愿意包容对方</p><p>在上面三起冲突中，无论它们的化解是风平浪静还是稍有波澜，安全型依恋风格的个体（或是双方）都起到了生理与情绪上的双重益处。乔治本能地包容了凯莉的人身攻击，对她的挫伤感担起了责任，通过包容对方而扭转了局面。若他属于回避型或是焦虑型，他的回应可能会是冷暴力，制造出更强烈的疏离和敌意。</p><p>同样地，弗兰克和珊迪也本可以坚定自己的立场毫不退让。珊迪完全可以说：“你猜怎么着？你想干什么随你的便，但我就得在城里面过周末！”，并且拒绝任何商量的余地。弗兰克也可以同样强硬，若是如此故步自封，他们将会度过许许多多没有对方的糟糕周末。只有两个人同时产生解决问题的意愿，他们才会找到两人都愿意采纳的解决方案，同时也不断地学习到与对方需求磨合的艺术。</p><p>5.有效地沟通双方的感受与需要：</p><p>由于汤姆（Tom）的工作特别忙，瑞贝卡（Rebecca）一周很难见到他，她感觉非常孤独。周末她常常会到附近姐姐家去。汤姆也不乐意跟她一块去，他更愿意躺在家里的沙发上好好放松一下。瑞贝卡通常不会对此有什么意见，但这个周六，汤姆度过尤其繁忙漫长的一周工作后，特别想一个人待着，但瑞贝卡却坚持要他同去。而对一周的繁重工作本来就不胜其烦的汤姆，自然是很强硬地拒绝同行。瑞贝卡不甘心被拒绝，还一直催他答应。汤姆更加逆反，毫不松口。最终，瑞贝卡说汤姆太自私了，她独自出门，而汤姆沉默地待在电视机前。</p><p>瑞贝卡的行为是典型的焦虑型依恋风格。由于丈夫这周的工作比往常还要繁忙，就更是激起了她的依恋机制，她异常需要两人待在一块。她需求的当务之急就是汤姆有空陪她——表示对她的在意，表示自己愿意跟她待在一起。但是，瑞贝卡没有直说这些，也没有解释到底什么在困扰自己，而是使用了防御行为——指责他太自私，还逼着他跟自己一起去姐姐家。而汤姆对于瑞贝卡突然的怒火中烧非常困惑——毕竟他以为自己不必要去她姐姐家，是二人达成的默契。</p><p>要是瑞贝卡直接说：“我知道你不想去我姐姐家，但要是你今天陪我去一次，我会非常开心，因为我已经一周没怎么见你了，实在不想错过和你待在一块儿的时间。”汤姆又会作何反应呢？</p><p>有效地表达出你的需求，比另一半魔法般地读出你的想法要好得多。这表示出你是一位活跃的讲述者，如此一来可以开启一段更加富有情感的对话。即使汤姆最终还是决定不跟瑞贝卡一起去，知道她的感受之后，他会选择另外的方式来安抚瑞贝卡：“你要是非让我跟你一起去，我还是会去的。但我真的需要歇会儿，比如我们俩今晚一起出去，就我们两个人？反正你也不是真的想让我待在你姐姐家，不是吗？我会妨碍你俩叙旧的。”</p><p>由依恋生物学避免冲突</p><p>当冲突产生的时候，其并不一定关乎一方对另一方做了什么，或者关乎双方如何妥协，甚至如何有效地表达自己。有时候，了解依恋关系的基本生物学原理，可以让你在冲突发生之前防患于未然。催产素是一种近年来备受新闻报道关注的荷尔蒙与神经肽，在依恋过程中担任着重要角色，起到了如下几个作用：促进女人分娩；增强依恋感；通过增强人们的信任感与合作感，以此来充当社会交往激素。在我们获得性高潮，甚至仅仅是相拥的时候，大脑中都会产生大量的催产素——这也就是为什么它还被称为“拥抱荷尔蒙”。</p><p>那么，催产素是如何用于化解冲突的呢？有时候我们和伴侣的相处时光，质量是很低的，特别是当双方对彼此的需求遭到抑制的时候。而神经科学研究发现，我们应该先转移自己的第一要务。在对伴侣的亲密感减弱的时候，我们也错过了催产素的分泌——而这也导致了我们对于周围世界减少了认同，也更容易陷入冲突。</p><p>因此，当下一次你决定跳过周日早晨的相拥时光，而一味追逐忙碌工作的时候，一定要三思而行。这一亲密举动足以在接下来几天里，让你们的亲密关系一定程度上免于陷入冲突。</p>',32)])])}const m=e(o,[["render",r]]);export{h as __pageData,m as default};
